def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Locate the full separator row or column.
    sep_row = next((r for r in range(h) if all(v == 2 for v in grid[r])), None)
    sep_col = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)

    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    cells = {(r, c) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != 2}
    if not cells:
        return out

    # The examples with multiple separate 8-connected shapes are unchanged.
    unseen = set(cells)
    components = 0
    while unseen:
        components += 1
        stack = [unseen.pop()]
        while stack:
            r, c = stack.pop()
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    p = (r + dr, c + dc)
                    if p in unseen:
                        unseen.remove(p)
                        stack.append(p)
    if components != 1:
        return out

    rs = [r for r, c in cells]
    cs = [c for r, c in cells]

    if sep_col is not None:
        if min(cs) > sep_col:
            target = max(cs) + 1
        else:
            target = min(cs) - 1
            # For a broad object, the indicated line coincides with its far edge.
            if max(cs) - min(cs) + 1 >= 5:
                target = min(cs)
        if 0 <= target < w:
            for r in range(h):
                out[r][target] = 8
    elif sep_row is not None:
        if min(rs) > sep_row:
            target = max(rs) + 1
        else:
            target = min(rs) - 1
        if 0 <= target < h:
            for c in range(w):
                out[target][c] = 8

    return out
