def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find the divider and the background color.
    divider_col = next((c for c in range(w)
                        if all(grid[r][c] == 2 for r in range(h))), None)
    divider_row = next((r for r in range(h)
                        if all(v == 2 for v in grid[r])), None)
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    obj = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] != background and grid[r][c] != 2]
    if not obj:
        return out

    if divider_col is not None:
        min_c = min(c for r, c in obj)
        max_c = max(c for r, c in obj)
        if max_c < divider_col:
            step = 1
            can_move = max_c + 1 < divider_col
            marker_c = min_c
            outside_c = min_c - 1
        else:
            step = -1
            can_move = min_c - 1 > divider_col
            marker_c = max_c
            outside_c = max_c + 1

        if can_move:
            for r, c in obj:
                out[r][c] = background
            for r, c in obj:
                out[r][c + step] = grid[r][c]
            for r in range(h):
                out[r][marker_c] = 8
        elif 0 <= outside_c < w:
            for r in range(h):
                out[r][outside_c] = 8

    elif divider_row is not None:
        min_r = min(r for r, c in obj)
        max_r = max(r for r, c in obj)
        if max_r < divider_row:
            step = 1
            can_move = max_r + 1 < divider_row
            marker_r = min_r
            outside_r = min_r - 1
        else:
            step = -1
            can_move = min_r - 1 > divider_row
            marker_r = max_r
            outside_r = max_r + 1

        if can_move:
            for r, c in obj:
                out[r][c] = background
            for r, c in obj:
                out[r + step][c] = grid[r][c]
            for c in range(w):
                out[marker_r][c] = 8
        elif 0 <= outside_r < h:
            for c in range(w):
                out[outside_r][c] = 8

    return out
